alter table public.profiles add column if not exists xp int not null default 0;
alter table public.profiles add column if not exists gold int not null default 120;
alter table public.profiles add column if not exists level int not null default 1;
alter table public.profiles add column if not exists claimed int[] not null default '{}';
alter table public.profiles add column if not exists inv jsonb not null default '[]';
alter table public.profiles add column if not exists own text[] not null default '{}';
alter table public.profiles add column if not exists eq jsonb not null default '{}';
alter table public.profiles add column if not exists eqp jsonb not null default '{}';
alter table public.profiles add column if not exists bio text not null default '';
alter table public.profiles add column if not exists fac text not null default '';
alter table public.profiles add column if not exists xp_day int not null default 0;
alter table public.profiles add column if not exists day date not null default current_date;
alter table public.profiles add column if not exists cd timestamptz;
alter table public.profiles add column if not exists quests jsonb not null default '{}';
alter table public.post_likes add column if not exists created_at timestamptz not null default now();
alter table public.posts add column if not exists reports int not null default 0;
create table if not exists public.like_awards (post_id uuid not null, user_id uuid not null, primary key (post_id, user_id));
alter table public.like_awards enable row level security;
create table if not exists public.reports (post_id uuid not null references public.posts(id) on delete cascade, reporter uuid not null default auth.uid() references auth.users(id) on delete cascade, reason text not null default '', created_at timestamptz not null default now(), primary key (post_id, reporter));
alter table public.reports enable row level security;
drop policy if exists "denuncias: criar" on public.reports;
create policy "denuncias: criar" on public.reports for insert to authenticated with check (reporter = auth.uid());
create table if not exists public.market (id uuid primary key default gen_random_uuid(), seller uuid not null references auth.users(id) on delete cascade, seller_name text not null, name text not null, price int not null check (price between 1 and 99999), icon text not null default '🎁', item jsonb not null, created_at timestamptz not null default now());
alter table public.market enable row level security;
drop policy if exists "mercado: ler" on public.market;
create policy "mercado: ler" on public.market for select to authenticated using (true);
drop policy if exists "posts: ler" on public.posts;
create policy "posts: ler" on public.posts for select to authenticated using (reports < 3 or author = auth.uid());
revoke insert, update, delete on public.profiles from anon, authenticated;
grant update (name, bio, fac, data) on public.profiles to authenticated;
revoke insert on public.posts from anon, authenticated;
grant insert (name, cls, fac, title, fr, text) on public.posts to authenticated;
create or replace function public.has_bad(t text) returns boolean language sql immutable as $$ select regexp_replace(translate(lower(coalesce(t,'')),'áàâãäéèêëíìîïóòôõöúùûüçñ013457@$','aaaaaeeeeiiiiooooouuuucnoieastas'),'(.)\1+','\1','g') ~ '\y(puta|puto|caralho|karalho|pora|merda|bosta|foda|foder|fodido|fodase|buceta|pqp|vsf|fdp|tnc|krl|viado|arombado|cuzao|cu|punheta|xereca|piroca|retardado|fuck|shit|bitch|cunt|dick|niger|niga|fagot)\y' $$;
create or replace function public.chk_bad() returns trigger language plpgsql as $$ declare t text; begin foreach t in array tg_argv loop if public.has_bad(to_jsonb(new)->>t) then raise exception 'Linguagem imprópria não é permitida'; end if; end loop; return new; end $$;
create or replace function public.rate_limit() returns trigger language plpgsql security definer set search_path = public as $$ declare n int; begin execute format('select count(*) from public.%I where author = $1 and created_at > now() - make_interval(secs => $2)', tg_table_name) into n using new.author, tg_argv[1]::int; if n >= tg_argv[0]::int then raise exception 'Calma, viajante: muitas mensagens seguidas'; end if; return new; end $$;
drop trigger if exists bad_posts on public.posts;
create trigger bad_posts before insert or update on public.posts for each row execute function public.chk_bad('text','name','title');
drop trigger if exists bad_comments on public.comments;
create trigger bad_comments before insert or update on public.comments for each row execute function public.chk_bad('text','name');
drop trigger if exists bad_chat on public.chat;
create trigger bad_chat before insert or update on public.chat for each row execute function public.chk_bad('text','name');
drop trigger if exists bad_profiles on public.profiles;
create trigger bad_profiles before insert or update on public.profiles for each row execute function public.chk_bad('name','bio');
drop trigger if exists bad_market on public.market;
create trigger bad_market before insert or update on public.market for each row execute function public.chk_bad('name');
drop trigger if exists rl_posts on public.posts;
create trigger rl_posts before insert on public.posts for each row execute function public.rate_limit('3','60');
drop trigger if exists rl_comments on public.comments;
create trigger rl_comments before insert on public.comments for each row execute function public.rate_limit('6','60');
drop trigger if exists rl_chat on public.chat;
create trigger rl_chat before insert on public.chat for each row execute function public.rate_limit('8','20');
create or replace function public.count_report() returns trigger language plpgsql security definer set search_path = public as $$ begin update posts set reports = reports + 1 where id = new.post_id; return null; end $$;
drop trigger if exists trg_count_report on public.reports;
create trigger trg_count_report after insert on public.reports for each row execute function public.count_report();
create or replace function public.grant_xp(u uuid, x int, g int, capped boolean) returns void language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; td date := (now() at time zone 'utc')::date; begin select * into p from profiles where id = u for update; if not found then return; end if; if p.day <> td then p.day := td; p.xp_day := 0; end if; if capped then x := least(x, greatest(150 - p.xp_day, 0)); if x = 0 then return; end if; p.xp_day := p.xp_day + x; end if; p.xp := p.xp + x; p.gold := p.gold + g; while p.xp >= p.level * 100 loop p.xp := p.xp - p.level * 100; p.level := p.level + 1; end loop; update profiles set xp = p.xp, gold = p.gold, level = p.level, xp_day = p.xp_day, day = p.day where id = u; end $$;
revoke execute on function public.grant_xp(uuid, int, int, boolean) from public, anon, authenticated;
create or replace function public.award_post() returns trigger language plpgsql security definer set search_path = public as $$ begin if (select count(*) from posts where author = new.author and created_at >= (current_date::timestamp at time zone 'utc')) <= 5 then perform grant_xp(new.author, case new.cls when 'Bardo' then 22 when 'Mago' then (case when char_length(new.text) >= 150 then 25 else 15 end) else 15 end, case new.cls when 'Ladino' then 15 else 10 end, true); end if; return null; end $$;
drop trigger if exists trg_award_post on public.posts;
create trigger trg_award_post after insert on public.posts for each row execute function public.award_post();
create or replace function public.award_like() returns trigger language plpgsql security definer set search_path = public as $$ declare pf text; mf text; au uuid; ins int; begin select fac, author into pf, au from posts where id = new.post_id; if au = new.user_id then return null; end if; insert into like_awards values (new.post_id, new.user_id) on conflict do nothing; get diagnostics ins = row_count; if ins = 1 then select fac into mf from profiles where id = new.user_id; if mf <> '' and mf = pf then perform grant_xp(new.user_id, 4, 2, true); else perform grant_xp(new.user_id, 2, 0, true); end if; end if; return null; end $$;
drop trigger if exists trg_award_like on public.post_likes;
create trigger trg_award_like after insert on public.post_likes for each row execute function public.award_like();
create or replace function public.award_comment() returns trigger language plpgsql security definer set search_path = public as $$ begin if (select count(*) from comments where author = new.author and created_at >= (current_date::timestamp at time zone 'utc')) <= 5 then perform grant_xp(new.author, 2, 1, true); end if; return null; end $$;
drop trigger if exists trg_award_comment on public.comments;
create trigger trg_award_comment after insert on public.comments for each row execute function public.award_comment();
create or replace function public.me() returns jsonb language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; td text := ((now() at time zone 'utc')::date)::text; ts timestamptz := (current_date::timestamp at time zone 'utc'); st jsonb := jsonb_build_array(jsonb_build_object('id', gen_random_uuid()::text, 'n', 'Chapéu de Bardo', 'k', 'hat', 'slot', 'head')); begin if auth.uid() is null then raise exception 'login necessario'; end if; insert into profiles (id, name, inv) values (auth.uid(), 'Viajante', st) on conflict do nothing; select * into p from profiles where id = auth.uid(); if p.inv = '[]'::jsonb and p.level = 1 and p.xp = 0 then update profiles set inv = st where id = p.id returning * into p; end if; if p.quests->>'day' is distinct from td then update profiles set quests = jsonb_build_object('day', td, 'got', '[]'::jsonb, 'd', 0, 's', 0) where id = p.id returning * into p; end if; return jsonb_build_object('name', p.name, 'bio', p.bio, 'fac', p.fac, 'data', p.data, 'gold', p.gold, 'xp', p.xp, 'level', p.level, 'claimed', to_jsonb(p.claimed), 'inv', p.inv, 'own', to_jsonb(p.own), 'eq', p.eq, 'eqp', p.eqp, 'cd', p.cd, 'day', td, 'got', p.quests->'got', 'n', jsonb_build_object('p', (select count(*) from posts where author = p.id and created_at >= ts), 'c', (select count(*) from post_likes where user_id = p.id and created_at >= ts), 'cm', (select count(*) from comments where author = p.id and created_at >= ts), 'd', coalesce((p.quests->>'d')::int, 0), 's', coalesce((p.quests->>'s')::int, 0))); end $$;
create or replace function public.claim_tier(l int) returns jsonb language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; nm text[] := array['Título: O Iniciado','Capuz Sombrio','Espada Curva de Aço Negro','Título Raro: Mestre dos Sinos','Lanterna das Almas','Manto da Névoa','Coroa de Corvos','Título Lendário: Eleito da Noite']; gd int[] := array[50,100,200,500,300,400,600,1000]; it jsonb; begin if l < 1 or l > 8 then raise exception 'nível inválido'; end if; perform me(); select * into p from profiles where id = auth.uid() for update; if p.level < l or l = any(p.claimed) then raise exception 'recompensa indisponível'; end if; it := jsonb_build_object('id', gen_random_uuid()::text, 'n', nm[l], 'k', l); if l in (2,3,7) then it := it || jsonb_build_object('slot', case l when 3 then 'weapon' else 'head' end); end if; update profiles set gold = gold + gd[l], claimed = claimed || l, inv = inv || it where id = p.id; return me(); end $$;
create or replace function public.claim_quest(i int) returns jsonb language plpgsql security definer set search_path = public as $$ declare m jsonb; k text[] := array['p','c','cm','d','s']; rq int[] := array[1,3,2,1,1]; xr int[] := array[20,25,20,10,15]; gr int[] := array[10,15,10,5,10]; got jsonb; begin if i < 0 or i > 4 then raise exception 'missão inválida'; end if; m := me(); got := m->'got'; if got @> to_jsonb(i) then raise exception 'missão já resgatada'; end if; if (m->'n'->>k[i+1])::int < rq[i+1] then raise exception 'missão incompleta'; end if; update profiles set quests = jsonb_set(quests, '{got}', got || to_jsonb(i)) where id = auth.uid(); perform grant_xp(auth.uid(), xr[i+1], gr[i+1], false); return me(); end $$;
create or replace function public.use_skill(cls text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; begin perform me(); select * into p from profiles where id = auth.uid() for update; if p.cd is not null and p.cd > now() then raise exception 'habilidade recarregando'; end if; if coalesce((p.quests->>'s')::int, 0) >= 20 then raise exception 'limite diário da habilidade'; end if; update profiles set cd = now() + interval '60 seconds', quests = jsonb_set(quests, '{s}', to_jsonb(coalesce((quests->>'s')::int, 0) + 1)) where id = p.id; perform grant_xp(p.id, 8, 15, false); return me(); end $$;
create or replace function public.roll_dice() returns int language plpgsql security definer set search_path = public as $$ declare r int := 1 + floor(random() * 20)::int; p profiles%rowtype; begin perform me(); select * into p from profiles where id = auth.uid() for update; if coalesce((p.quests->>'d')::int, 0) >= 30 then raise exception 'limite diário de dados'; end if; update profiles set quests = jsonb_set(quests, '{d}', to_jsonb(coalesce((quests->>'d')::int, 0) + 1)), gold = gold + (case when r = 20 then 5 else 0 end) where id = p.id; return r; end $$;
create or replace function public.shop(sid text, unq boolean) returns jsonb language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; ids text[] := array['t1','t2','t3','f1','f2','f3']; pr int[] := array[150,300,700,200,400,600]; vs text[] := array['Vigia Insone','Corvo do Conde','Eleito da Lua Rubra','#d23a4c','#f3d178','#7fb0e8']; ix int := array_position(ids, sid); begin if ix is null then raise exception 'item inválido'; end if; perform me(); select * into p from profiles where id = auth.uid() for update; if not (sid = any(p.own)) then if p.gold < pr[ix] then raise exception 'ouro insuficiente'; end if; update profiles set gold = gold - pr[ix], own = own || sid where id = p.id; end if; update profiles set eq = case when unq then eq - substr(sid,1,1) else eq || jsonb_build_object(substr(sid,1,1), vs[ix]) end where id = p.id; return me(); end $$;
create or replace function public.equip(slot text, iid text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; begin if slot not in ('head','weapon') then raise exception 'slot inválido'; end if; perform me(); select * into p from profiles where id = auth.uid() for update; if iid is null then update profiles set eqp = eqp - slot where id = p.id; else if not exists (select 1 from jsonb_array_elements(p.inv) x where x->>'id' = iid and x->>'slot' = slot) then raise exception 'item não equipável'; end if; update profiles set eqp = eqp || jsonb_build_object(slot, iid) where id = p.id; end if; return me(); end $$;
create or replace function public.list_item(nm text, pr int) returns jsonb language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; it jsonb; ix int := 0; fx int; begin if pr is null or pr < 1 or pr > 99999 then raise exception 'preço inválido'; end if; perform me(); select * into p from profiles where id = auth.uid() for update; if (select count(*) from market where seller = p.id) >= 10 then raise exception 'limite de 10 anúncios'; end if; for it in select * from jsonb_array_elements(p.inv) loop if lower(it->>'n') = lower(trim(nm)) and not exists (select 1 from jsonb_each_text(p.eqp) e where e.value = it->>'id') then fx := ix; exit; end if; ix := ix + 1; end loop; if fx is null then raise exception 'item não encontrado (não pode estar equipado)'; end if; it := p.inv -> fx; insert into market (seller, seller_name, name, price, icon, item) values (p.id, p.name, it->>'n', pr, coalesce(it->>'e', '🎁'), it); update profiles set inv = inv - fx where id = p.id; return me(); end $$;
create or replace function public.buy_item(mid uuid) returns jsonb language plpgsql security definer set search_path = public as $$ declare m market%rowtype; p profiles%rowtype; it jsonb; begin perform me(); select * into m from market where id = mid for update; if not found then raise exception 'anúncio indisponível'; end if; if m.seller = auth.uid() then raise exception 'item próprio'; end if; select * into p from profiles where id = auth.uid() for update; if p.gold < m.price then raise exception 'ouro insuficiente'; end if; it := m.item || jsonb_build_object('id', gen_random_uuid()::text); update profiles set gold = gold - m.price, inv = inv || it where id = p.id; update profiles set gold = gold + m.price where id = m.seller; delete from market where id = m.id; return me(); end $$;
create or replace function public.cancel_listing(mid uuid) returns jsonb language plpgsql security definer set search_path = public as $$ declare m market%rowtype; begin perform me(); select * into m from market where id = mid and seller = auth.uid() for update; if not found then raise exception 'anúncio não encontrado'; end if; update profiles set inv = inv || m.item where id = m.seller; delete from market where id = m.id; return me(); end $$;
